// Sandcastle 项目配置：编排脚本里随项目变的部分（由 sandpipe onboard 生成，按需修改）。
// Sandcastle project config: the project-specific part of the pipeline (generated by sandpipe onboard, edit as needed).
// 字段说明见 sandpipe 的 docs/config.zh-CN.md。
// Fields are described in sandpipe's docs/config.md.
import { defineProject } from "sandpipe";

export default defineProject({
  // forge: githubForge(),  默认 GitHub（宿主机的 gh）
  // forge: githubForge(),  GitHub by default (the host's gh)
  // issue、PR、评论和终端输出用什么语言（"zh" / "en"）
  // Language for issues, PRs, comments and terminal output ("zh" / "en")
  language: "zh",
  // 自动合并按 ADR 0004 分阶段放开：#57、#60、#64 已完成，只开 PR 模式下连续 5 张 PR（#128 #130 #131 #136 #137）人没改就合了。
  // 受保护路径、需要人判断、浏览器验收没过、main-broken 时仍留 PR 给人。
  // Auto-merge enabled in stages per ADR 0004: #57, #60, #64 are done, and 5 PRs in a row (#128 #130 #131 #136 #137) were merged unchanged in PR-only mode.
  // Protected paths, items needing a human, failed browser checks and main-broken still leave the PR for a human.
  autoMerge: true,
  // 同时实现几张票：受测试依赖的服务（连接数）与机器负载限制
  // How many tickets to implement at once: limited by the services the tests use (connections) and machine load
  // 本仓库测试不依赖外部服务，并行度受模型额度和机器负载限制；2 张同时做。
  // This repo's tests use no external services; parallelism is bounded by model quota and machine load, so 2 at a time.
  maxParallel: 2,

  install: {
    // 沙箱建好后装依赖（容器是 linux，宿主机拷进来的原生包可能用不了）
    // Install dependencies once the sandbox is ready (the container is linux; native packages copied from the host may not work)
    onSandboxReady: "pnpm install --frozen-lockfile",
    copyToWorktree: ["node_modules"],
  },

  isolation: {
    env: (runId) => ({
      // 测试依赖外部服务（数据库、缓存、对象存储）时，在这里给每张票独立的库名 / 前缀（加 runId）。
      // If tests use external services (database, cache, object storage), give each ticket its own database name / prefix here (add runId).
      SANDCASTLE_RUN_ID: runId,
    }),
    // cleanup: async (runId) => { /* 关沙箱后删掉这张票的测试库 */ },
    // cleanup: async (runId) => { /* drop this ticket's test database after the sandbox closes */ },
  },

  gate: {
    // 合并门槛：退出码 0 算通过。输出约定（GATE_TIER / GATE_FLAKY，可以不用）见 docs/config.zh-CN.md。
    // Merge gate: exit code 0 means pass. Output conventions (GATE_TIER / GATE_FLAKY, optional) are in docs/config.md.
    script: () => "pnpm typecheck && pnpm test && pnpm check:comments && pnpm build",
    testFile: /\S+\.(test|spec)\.[cm]?[jt]sx?/,
    typecheck: "pnpm typecheck",
  },

  // 受保护路径（按探测结果给的默认值：快照、CI workflow、迁移目录……）：票改到命中的文件就不自动合并，留 PR 给人看。lockfile 等需要的自己加，见 sandpipe 的 docs/config.zh-CN.md。
  // Protected paths (defaults from what was detected: snapshots, CI workflows, migration directory…): a ticket touching a matching file isn't auto-merged; the PR is left for a human. Add lockfiles etc. yourself if needed, see sandpipe's docs/config.md.
  // 本仓库自举：决定「能不能合进来」的文件不让 agent 自己批准（ADR 0004、0006）。
  // Self-hosting: files that decide what may be merged aren't approved by the agent itself (ADR 0004, 0006).
  protectedPaths: [
    /^\.github\/workflows\//,
    /^prompts\//,
    /^\.sandcastle\//,
    /^claude\//,
    /^\.claude\//,
    /^scripts\//,
    /^package\.json$/,
    /^src\/(merge-checks|merge-flow|re-review|browser-gate|gate-queue|trust|protected-paths|waiting-main)\.ts$/,
    /^src\/forges\/github\.ts$/,
  ],

  // 几张票会同时往末尾追加的索引文件（CHANGELOG、测试目录……），列在这里的不算「改同一个文件」，可以并行。
  // Index files several tickets append to at once (CHANGELOG, test catalog…); files listed here don't count as "changing the same file", so those tickets can run in parallel.
  // 几乎每张票都往 CHANGELOG 的 Unreleased 加一条，冲突时 rebase 两边都保留。
  // Nearly every ticket adds an entry under CHANGELOG's Unreleased; rebase keeps both sides on conflict.
  appendOnlyFiles: ["CHANGELOG.md"],
});
